#include <bits/stdc++.h>
using namespace std;

int lengthOfLongestSubstring(const string& s) {
    unordered_map<char, int> lastIndex;
    int start = 0, ans = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        auto it = lastIndex.find(s[i]);
        if (it != lastIndex.end() && it->second >= start)
            start = it->second + 1;
        lastIndex[s[i]] = i;
        ans = max(ans, i - start + 1);
    }
    return ans;
}

